package edu.pe.cibertec.saibm.membresia.domain.model;
import java.time.*; import java.util.UUID;
public record Plan(UUID id,String code,String name,int reservationLimit,int version,Instant validFrom,Instant validUntil,boolean active,String legacyId){public Plan{if(id==null||code==null||code.isBlank()||name==null||name.isBlank()||reservationLimit<0||version<1||validFrom==null)throw new IllegalArgumentException("Invalid plan");validFrom=micros(validFrom);validUntil=validUntil==null?null:micros(validUntil);}public boolean validAt(Instant at){return active&&!at.isBefore(validFrom)&&(validUntil==null||at.isBefore(validUntil));}public Plan revise(String n,int limit,Instant from,Instant until){return new Plan(UUID.randomUUID(),code,n,limit,version+1,from,until,true,legacyId);}public Plan closeAt(Instant until){return new Plan(id,code,name,reservationLimit,version,validFrom,until,false,legacyId);}public Plan deactivate(){return new Plan(id,code,name,reservationLimit,version,validFrom,validUntil,false,legacyId);}private static Instant micros(Instant value){return value.truncatedTo(java.time.temporal.ChronoUnit.MICROS);}}
